      const vel = velicine3({ ...pocetneVrijednosti2(s), [k.id]: v });
      const t = isNum(cilj.vrijednost) ? cilj.vrijednost : vel[cilj.vrijednost];
      return { q: vel[cilj.velicina], t, d: vel[cilj.velicina] - t };
